 "content": "def transform(grid):
    """Fill the interiors of rectangular outline objects."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0 = min(y for y, x in comp); r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp); c1 = max(x for y, x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                         if y in (r0,r1) or x in (c0,c1)}
            if comp != perimeter:
                continue
            fill = 2 if color == 6 else 7
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    out[y][x] = fill
    return out

if __name__ == '__main__':
    pass
